<script setup lang="ts">import{ref,computed}from'vue';import Tooltip from'./Tooltip.vue';import DOMPurify from'dompurify'
const p=defineProps<{code:string;isStreaming?:boolean}>()
const cl=ref(false);const vm=ref<'preview'|'code'>('preview');const cd=ref(false)
const sc=computed(()=>{if(!p.code)return'';let raw:string;if(p.code.trim().startsWith('<svg')){raw=p.code}else{const m=p.code.match(/<svg[\s\S]*?<\/svg>/i);raw=m?m[0]:p.code}try{return DOMPurify.sanitize(raw,{FORBID_TAGS:['script','foreignObject']})}catch{return''}})
async function hc(){try{await navigator.clipboard.writeText(p.code);cd.value=true;setTimeout(()=>cd.value=false,1500)}catch{}}
function hd(){const b=new Blob([p.code],{type:'image/svg+xml'});const u=URL.createObjectURL(b);const a=document.createElement('a');a.download=`svg-${Date.now()}.svg`;a.href=u;a.click();URL.revokeObjectURL(u)}
</script>
<template><div class="svg-card"><div class="svg-inner" :class="{'is-open':!cl}"><div class="svg-hdr" @click="cl=!cl"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" style="color:var(--accent)"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg><span class="svg-title">SVG Preview</span>
<div class="svg-actions" @click.stop><Tooltip text="Preview" position="bottom"><button class="icn-btn" :class="{active:vm==='preview'}" @click="vm='preview'"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg></button></Tooltip><Tooltip text="Source" position="bottom"><button class="icn-btn" :class="{active:vm==='code'}" @click="vm='code'"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><polyline points="16 18 22 12 16 6"/><polyline points="8 6 2 12 8 18"/></svg></button></Tooltip>
<template v-if="!isStreaming"><Tooltip text="Copy SVG" position="bottom"><button class="icn-btn" @click="hc"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg></button></Tooltip><Tooltip text="Download SVG" position="bottom"><button class="icn-btn" @click="hd"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg></button></Tooltip></template></div>
<span class="svg-arrow" :class="{open:!cl}"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg></span></div>
<div v-if="!cl" class="svg-body"><div v-if="vm==='preview'" class="svg-preview" v-html="sc"/><pre v-else class="svg-code">{{code}}</pre></div></div></div></template>
